  --primary: hsl(333.3 42.83% 45.9%);
  --primary-foreground: hsl(300 50% 100%);
  --secondary: hsl(314.61 64.46% 85.81%);
  --secondary-foreground: hsl(295.86 40% 34%);
  --muted: hsl(310.5 57.72% 93.35%);
  --muted-foreground: hsl(295.56 31.58% 39.92%);
  --accent: hsl(314.61 64.46% 85.81%);
  --accent-foreground: hsl(295.86 40% 34%);
  --destructive: hsl(357.38 45.39% 46.03%);
  --destructive-foreground: hsl(300 50% 100%);
  --border: hsl(304.86 60.25% 84.27%);
  --input: hsl(317.25 47.19% 83.06%);
  --ring: hsl(332.99 71.83% 50.03%);
  --chart-1: hsl(318 74.42% 48.73%);
  --chart-2: hsl(273.71 92.69% 37.78%);
  --chart-3: hsl(197.52 32.49% 24.5%);
  --chart-4: hsl(43.17 73.36% 65.26%);
